var EPS = 0.001; // faqat suzuvchi nuqta xatosi uchun
function yol(o, p){ return String(p).split(".").reduce(function(a, k){ return a == null ? undefined : a[k]; }, o); }
function kerak(v, nom){ if (v == null || (typeof v === "number" && isNaN(v))) { X.push("qoida topilmadi: " + nom); return null; } return v; }
function r1(x){ return Math.round(x * 10) / 10; }
function t0(s){ return Number(s.boshlanish_s) || 0; }
function t1(s){ return t0(s) + (Number(s.davomiylik_s) || 0); }
function tok(s){ return String(s || "").toLocaleLowerCase("tr").replace(/[^\p{L}\p{N}\s]+/gu, "").split(/\s+/).filter(Boolean); }
function sozSoni(s){ return String(s || "").split(/\s+/).filter(function(w){ return /[\p{L}\p{N}]/u.test(w); }).length; }
if (j.xato) X.push("PARSE_FAIL: prodyuser javobi JSON emas — faqat JSON qaytar");
var S = ((j.reja || {}).sahnalar) || [];
if (!j.xato && !S.length) X.push("reja.sahnalar bo'sh");
var MANBA_V = ["V_MANBA_KARTA", "V_MANBA_SAHIFA"];
var KUTUB = ["V_DONUT","V_WAFFLE","V_ORALIQ","V_USTUN","V_CHIZIQ","V_SXEMA","V_KATTA_RAQAM","V_MANBA_KARTA","V_MANBA_SAHIFA","V_KALIT_SOZ","V_AVATAR_TOLIQ","V_GIBRID"];
var mh = $("PR · manba_havolalari").all().map(function(i){ return i.json; });
var fIds = (j.faktlar || []).map(function(f){ return f.s_id; });
function nom(s, i){ return (s.n || i + 1) + "-sahna"; }
if (S.length) {
  // a) ilgak
  var ilgak = kerak(pq.ilgak_s, "platforma_qoida.ilgak_s");
  if (ilgak != null && t1(S[0]) > ilgak + EPS) X.push("a) 1-sahna " + r1(t1(S[0])) + " s da tugaydi, ilgak ≤ " + ilgak + " s bo'lishi kerak (2,5 so'z/s hisobida 1-sahna tts_parcha'si ≤ " + Math.floor(ilgak * 2.5) + " so'z yoki 2-sahna sinxron_soz'i shu so'zlar ichida bo'lsin)");
  var v0 = String(S[0].vizual || "");
  if (!/^V_/.test(v0) || v0 === "V_AVATAR_TOLIQ" || MANBA_V.indexOf(v0) >= 0) X.push("a) 1-sahnada grafik (V_*) yo'q: " + (v0 || "—"));
  // b) yolg'iz avatar
  var avMax = kerak(yol(q, "avatar.uzluksiz_kadr_max_s." + mk), "qoidalar.avatar.uzluksiz_kadr_max_s." + mk);
  var run = 0, runN = null;
  S.forEach(function(s, i){ var yz = s.vizual === "V_AVATAR_TOLIQ"; if (yz) { run += Number(s.davomiylik_s) || 0; if (runN == null) runN = nom(s, i); } if (!yz || i === S.length - 1) { if (avMax != null && run > avMax + EPS) X.push("b) yolg'iz avatar kadri (" + runN + " dan) " + r1(run) + " s, maks " + avMax + " s — grafikka o't"); run = 0; runN = null; } });
  // c) patern uzish
  var pat = kerak(yol(q, "neyro.patern_uzish_s." + mk), "qoidalar.neyro.patern_uzish_s." + mk);
  var jami = t1(S[S.length - 1]) - t0(S[0]), seg = 1;
  for (var k = 1; k < S.length; k++) if (S[k].vizual !== S[k - 1].vizual) seg++;
  var ort = seg ? jami / seg : jami;
  if (pat != null && ort > pat + EPS) X.push("c) vizual almashishlar orasidagi o'rtacha vaqt " + r1(ort) + " s (" + seg + " ta vizual, " + r1(jami) + " s), maks " + pat + " s");
  S.forEach(function(s, i){ if (!((Number(s.davomiylik_s) || 0) > EPS)) X.push("c) " + nom(s, i) + " davomiyligi 0 s — sinxron_soz TTS matnidagi aniq so'z bo'lsin va oldingi sahnaning sinxron_soz'idan keyin kelsin"); });
  var ekMax = kerak(yol(q, "kognitiv.ekran_matni_soz_max"), "qoidalar.kognitiv.ekran_matni_soz_max");
  var kech = kerak(yol(q, "manba.da_vo_manba_kechikish_s"), "qoidalar.manba.da_vo_manba_kechikish_s");
  var korilgan = [];
  var taqiq = yol(q, "huquq.taqiq") || [], ibora = [];
  taqiq.forEach(function(t){ String(t).split("/").forEach(function(p){ var w = tok(p); if (w.length) ibora.push(w.slice(0, 2).join(" ")); }); });
  var akk = (((j.vizual_tizim || {}).akkaunt || {})[j.akkaunt] || {}).taqiq_sozlar || [];
  var ruxsatHavola = mh.map(function(r){ return r.havola; }).filter(Boolean);
  S.forEach(function(s, i){
    var n = nom(s, i), ek = String(s.ekran_yozuvi || ""), isM = MANBA_V.indexOf(s.vizual) >= 0;
    if (KUTUB.indexOf(s.vizual) < 0) X.push("i) " + n + ": vizual kutubxonada yo'q — " + s.vizual);
    // d) ekran yozuvi
    if (ekMax != null && sozSoni(ek) > ekMax) X.push("d) " + n + " ekran_yozuvi " + sozSoni(ek) + " so'z, maks " + ekMax);
    if (tok(ek).length && tok(ek).join(" ") === tok(s.tts_parcha).join(" ")) X.push("d) " + n + " ekran_yozuvi tts_parcha bilan so'zma-so'z bir xil — faqat kalit so'z/raqam qoldir");
