    }
    if (s.vizual === "V_KATTA_RAQAM") { var juft = [S[i - 1], S[i + 1]].filter(Boolean).some(function(x){ return x.vizual === "V_DONUT" || x.vizual === "V_WAFFLE"; }); if (!juft) X.push("e) " + n + ": V_KATTA_RAQAM yolg'iz — qo'shni sahnada V_DONUT yoki V_WAFFLE bo'lsin yoki boshqa vizual tanla"); }
