    if (s.s_id && !isM && korilgan.indexOf(s.s_id) < 0 && kech != null) {
      korilgan.push(s.s_id);
      var ok = MANBA_V.indexOf(s.manba_vizual) >= 0 || S.some(function(m){ return MANBA_V.indexOf(m.vizual) >= 0 && m.s_id === s.s_id && t0(m) >= t0(s) - EPS && t0(m) <= t1(s) + kech + EPS; });
      if (!ok) X.push("f) " + n + " da'vosi (" + s.s_id + ") dan keyin ≤ " + kech + " s ichida manba vizuali yo'q");
    }
