    }
    // i) huquq va mahsulot
    var matn = (ek + " " + JSON.stringify(s.malumot || {}) + " " + (s.vizual || "") + " " + (s.harakat || "")).toLocaleLowerCase("tr");
    ibora.forEach(function(b){ if (b && matn.indexOf(b) >= 0) X.push("i) " + n + ": huquqiy taqiq — " + b); });
    var mt = (ek + " " + (s.tts_parcha || "") + " " + JSON.stringify(s.malumot || {})).toLocaleLowerCase("tr");
    akk.forEach(function(w){ var re = new RegExp("(^|[^\\p{L}])" + String(w).toLocaleLowerCase("tr").replace(/[.*+?^$()|[\]\\]/g, "\\$&") + "($|[^\\p{L}])", "u"); if (re.test(mt)) X.push("i) " + n + ": mahsulot/taqiq so'z — " + w); });
