  });
  // h) yakun / va'da
  var oxirgi = S[S.length - 1];
  if (mk === "tiktok" || mk === "reel") { var ochiq = /\?/.test(String(oxirgi.ekran_yozuvi || "") + " " + String(oxirgi.tts_parcha || "")) || oxirgi.halqa === true; if (!ochiq) X.push("h) oxirgi sahna ochiq savol (ekran_yozuvi \"?\" bilan) yoki halqa (halqa:true) bilan tugashi kerak"); }
