// PR · Vaqt hisobi — sahna vaqtlari TTS bo'yicha. alignment bo'lsa: boshlanish_s = sinxron_soz vaqti; bo'lmasa 2,5 so'z/s taxmin.
var SUR = 2.5; // so'z/s — taxmin (alignment yo'q bo'lsa)
var j = $json;
if (j.xato || !j.reja) return { json: j };
var S = (j.reja.sahnalar || []).map(function(s){ return Object.assign({}, s); });
function tok(s){ return String(s || "").toLocaleLowerCase("tr").replace(/[^\p{L}\p{N}\s]+/gu, "").split(/\s+/).filter(Boolean); }
// 1) So'z vaqt jadvali T = [{w, t}]
var T = [], oxir = 0, usul = "taxmin_" + SUR + "_soz_s";
var al = j.alignment || j.tts_alignment || null;
if (al && Array.isArray(al.words) && al.words.length) {
  al.words.forEach(function(x){ var w = tok(x.word || x.text || x.soz)[0]; var t = Number(x.start != null ? x.start : (x.boshlanish != null ? x.boshlanish : x.start_s)); if (w && !isNaN(t)) T.push({ w: w, t: t }); var e = Number(x.end != null ? x.end : x.tugash); if (!isNaN(e)) oxir = Math.max(oxir, e); });
  usul = "alignment";
} else if (al && Array.isArray(al.characters) && Array.isArray(al.character_start_times_seconds)) {
  var cur = "", curT = null;
  al.characters.forEach(function(ch, k){ var t = Number(al.character_start_times_seconds[k]); if (/\s/.test(ch)) { if (cur) { var w = tok(cur)[0]; if (w) T.push({ w: tok(cur).join(""), t: curT }); } cur = ""; curT = null; } else { if (curT == null) curT = t; cur += ch; } });
  if (cur) { var w2 = tok(cur).join(""); if (w2) T.push({ w: w2, t: curT }); }
  var ends = al.character_end_times_seconds || []; oxir = ends.length ? Number(ends[ends.length - 1]) : (T.length ? T[T.length - 1].t : 0);
  usul = "alignment";
}
var W = tok(j.tts_matn);
if (!T.length) { T = W.map(function(w, i){ return { w: w, t: i / SUR }; }); oxir = W.length / SUR; }
if (!oxir && T.length) oxir = T[T.length - 1].t;
function topish(seq, from){ if (!seq.length) return -1; for (var pass = 0; pass < 2; pass++) { for (var k = (pass ? 0 : from); k <= T.length - seq.length; k++) { var ok = true; for (var m = 0; m < seq.length; m++) { if (T[k + m].w !== seq[m]) { ok = false; break; } } if (ok) return k; } } return -1; }
// 2) Har sahna boshlanishi
var kursor = 0, oldingi = 0, ogoh = [];
S.forEach(function(s, i){
  var P = tok(s.tts_parcha), Y = tok(s.sinxron_soz);
  var pIdx = P.length ? topish(P, kursor) : -1;
  var yIdx = Y.length ? topish(Y, pIdx >= 0 ? pIdx : kursor) : -1;
  var idx = yIdx >= 0 ? yIdx : pIdx;
  var t;
  if (i === 0) t = 0;
  else if (idx >= 0) t = T[idx].t;
  else { t = oldingi; ogoh.push((s.n || i + 1) + "-sahna: sinxron_soz/tts_parcha TTS matnida topilmadi"); }
  if (t < oldingi) { ogoh.push((s.n || i + 1) + "-sahna: sinxron_soz oldingi sahnadan oldin keladi"); t = oldingi; }
  s.vaqt_asl = { boshlanish_s: s.boshlanish_s, davomiylik_s: s.davomiylik_s };
  s.boshlanish_s = Math.round(t * 100) / 100;
  if (pIdx >= 0) kursor = Math.max(kursor, pIdx); else if (idx >= 0) kursor = Math.max(kursor, idx);
  oldingi = t;
});
S.forEach(function(s, i){ var keyin = i < S.length - 1 ? S[i + 1].boshlanish_s : oxir; s.davomiylik_s = Math.round(Math.max(0, keyin - s.boshlanish_s) * 100) / 100; });
// 3) Qoplash: tts_parcha'lar birlashtirilganda tts_matn'ni to'liq qoplashi shart
